<?php
namespace App\Http\Controllers\Api;
use App\Http\Requests\EnterpriseRequest; use App\Http\Requests\MasterIndexRequest; use App\Http\Resources\CompanyResource; use App\Models\Company; use App\Repositories\EnterpriseRepository; use App\Services\EnterpriseService;
class CompanyController extends BaseApiController { private EnterpriseService $service; public function __construct(){ $this->service=new EnterpriseService(new EnterpriseRepository(new Company)); } public function index(MasterIndexRequest $r){$this->authorize('viewAny',Company::class);return $this->respondWithResource(CompanyResource::collection($this->service->paginate($r->validated())),'Companies retrieved successfully.');} public function store(EnterpriseRequest $r){return $this->respondSuccess(new CompanyResource($this->service->create($r->validated())),'Company created successfully.',201);} public function show(Company $company){$this->authorize('view',$company);return $this->respondSuccess(new CompanyResource($company));} public function update(EnterpriseRequest $r,Company $company){return $this->respondSuccess(new CompanyResource($this->service->update($company,$r->validated())),'Company updated successfully.');} public function destroy(Company $company){$this->service->delete($company);return $this->respondSuccess(null,'Company deleted successfully.');} }
